#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Complex {
    pub re: i32,
    pub im: i32,
}

pub fn real_if_close(arr: Vec<Complex>, tol: i32) -> Vec<Complex> {
    // fixed machine epsilon = 2
    let threshold = tol.saturating_mul(2);
    // check if every imaginary part is "close to zero"
    if arr.iter().all(|c| c.im.abs() <= threshold) {
        // set all imaginary parts to zero
        arr.into_iter()
            .map(|c| Complex { re: c.re, im: 0 })
            .collect()
    } else {
        // return unchanged
        arr
    }
}

